// U.S. Census Bureau 2025 cartographic states, 1:5,000,000.
// Source: https://www2.census.gov/geo/tiger/GENZ2025/shp/cb_2025_us_state_5m.zip
// Coordinates rounded to five decimals; boundaries are for editorial display.
globalThis.StudioStatesReady=(async()=>{const bytes=Uint8Array.from(atob(''),c=>c.charCodeAt(0));const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));globalThis.StudioStates=JSON.parse(await new Response(stream).text());})();
